import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Spell knowledge and Core Patterns","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/magic/spell-knowledge.md","filePath":"en/game-design/magic/spell-knowledge.md"}'),r={name:"en/game-design/magic/spell-knowledge.md"};function s(o,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="spell-knowledge-and-core-patterns" tabindex="-1">Spell knowledge and Core Patterns <a class="header-anchor" href="#spell-knowledge-and-core-patterns" aria-label="Permalink to &quot;Spell knowledge and Core Patterns&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; listed decisions remain Unresolved. Existing Accepted foundations retain their scope. <strong>Implementation:</strong> no Batch 04 gameplay implementation established. <strong>Availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation reconciliation only, not runtime validation. <strong>Reviewed:</strong> 2026-10-09 against Batch 04 and <a href="/Syrolands-Public/en/game-design/magic.html">earlier magic design</a>.</p><p><a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/magic.html">Magic overview</a> · <a href="/Syrolands-Public/en/game-design/magic/status-and-open-questions.html">Status and open questions</a></p><h2 id="a-learned-structure-not-a-universal-spell-builder" tabindex="-1">A learned structure, not a universal spell builder <a class="header-anchor" href="#a-learned-structure-not-a-universal-spell-builder" aria-label="Permalink to &quot;A learned structure, not a universal spell builder&quot;">​</a></h2><p>A spell consists of a stable <strong>Core Pattern</strong>, optional learned modifiers and execution. It is neither merely a hardcoded button nor an unrestricted freeform construction sandbox. Fireball, Ice Lance, Heal, Remove Curse and Teleport are illustrative identities, not an approved catalogue.</p><p>A Core Pattern can define family/affinity, delivery shape, base range, targeting model, execution Difficulty, mana/resource cost, injury/utility behavior and relevant armor, limb or Concentration interactions. Its identity is stable enough to learn, teach, inscribe, preserve, discuss and build variants around. Exact metadata and spell definitions need later design.</p><h2 id="knowledge-skill-and-practice-are-separate" tabindex="-1">Knowledge, skill and practice are separate <a class="header-anchor" href="#knowledge-skill-and-practice-are-separate" aria-label="Permalink to &quot;Knowledge, skill and practice are separate&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Proposed meaning</th></tr></thead><tbody><tr><td>Knowledge</td><td>A permanently learned pattern or modifier; obtained separately from skill</td></tr><tr><td>Magery</td><td>General execution capability, control and consistency; eligibility does not guarantee reliability</td></tr><tr><td>Familiarity</td><td>Practice with an individual Core Pattern, outside the skillcap</td></tr><tr><td>Active Memory</td><td>Limited prepared access; knowing a pattern does not make every variant immediately ready</td></tr><tr><td>Wider Mastery</td><td>Earlier discipline/affinity specialization proposal; not synonymous with per-spell Familiarity</td></tr></tbody></table><p><a href="/Syrolands-Public/en/game-design/magic.html#attempt-floor-versus-execution-difficulty">Attempt floor versus Difficulty</a> remains authoritative for the proposal: meeting a threshold does not grant knowledge or perfect success. <a href="/Syrolands-Public/en/game-design/magic.html#fizzle-versus-interruption">Fizzle versus interruption</a> keeps structural execution failure separate from disruption under pressure.</p><h2 id="discovery-has-provenance" tabindex="-1">Discovery has provenance <a class="header-anchor" href="#discovery-has-provenance" aria-label="Permalink to &quot;Discovery has provenance&quot;">​</a></h2><p>Teachers, academies, schools, orders, grimoires, manuscripts, ruins, cultures, magical sites, creatures, rituals, experimentation and appropriately bounded player teaching can transmit knowledge. Geography, history and social relationships should matter. Reaching 70 Magery must not automatically unlock a spell.</p><p>The existing <a href="/Syrolands-Public/en/game-design/magic.html#knowledge-and-world-institutions">institution, admission and standing model</a> retains its four independent dimensions: discipline, affinity, technique and tradition. Batch 04&#39;s Core Pattern clarifies spell identity; it does not collapse these dimensions or finalize every school. Knowledge retention on loss of institutional favor remains the earlier proposed direction.</p><p>Learning from zero and ordinary skill bands belong to <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">Skills &amp; Skillcap</a>; <a href="/Syrolands-Public/en/game-design/characters/techniques-and-specialization.html">techniques and schools</a> own the shared progression model. <a href="/Syrolands-Public/en/game-design/professions/inscription.html">Inscription</a> preserves and transmits structures only within explicit teaching rules; a purchasable casting scroll is not automatically permanent learning.</p><h2 id="localized-effects-and-authority" tabindex="-1">Localized effects and authority <a class="header-anchor" href="#localized-effects-and-authority" aria-label="Permalink to &quot;Localized effects and authority&quot;">​</a></h2><p>Each pattern needs an appropriate <a href="/Syrolands-Public/en/game-design/magic.html#localized-magic-and-injury">localized magic profile</a>. Area exposure, local trauma, burning, cold impairment, blunt force and Concentration disruption are candidates. Anatomy may support deliberate regional casting only where the pattern permits it. Not every spell can target every limb, and selecting a limb does not guarantee impact.</p><p>The server owns learned knowledge, eligibility, resources and cast outcomes. The client displays permitted knowledge and sends intent. No spell schema, protocol allocation or save format is selected.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Final pattern catalogue and taxonomy; learning prerequisites; allowed player teaching and copying; restrictions on forbidden patterns; qualitative progression feedback; interaction between per-pattern Familiarity and wider Mastery; per-spell anatomical and utility contracts. No discovery odds or execution formula is finalized.</p>',18)])])}const g=a(r,[["render",s]]);export{m as __pageData,g as default};
